LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (4,0,'2026-09-30 07:04:58','2026-09-30 07:04:58','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-09-30 07:04:58','2026-09-30 07:04:58','',0,'http://localhost/realestate/index.php/2026/09/30/navigation/',0,'wp_navigation','',0),(5,0,'2026-09-30 12:36:31','2026-09-30 07:06:31','','Default Kit','','publish','closed','closed','','default-kit','','','2026-09-30 12:36:31','2026-09-30 07:06:31','',0,'http://localhost/realestate/?p=5',0,'elementor_library','',0),(9,0,'2026-09-30 07:13:32','2026-09-30 01:43:32','A bright, well-kept independent house on a quiet lane off Sahastradhara Road, ten minutes from the ISBT and main markets.\n\nThe ground floor has a spacious living and dining area with a modular kitchen; bedrooms are on the upper floor with attached bathrooms. Covered parking for two cars and a small front lawn.','3 BHK Independent House near Sahastradhara Road','A bright, well-kept independent house on a quiet lane off Sahastradhara Road, ten minutes from the ISBT and main markets.','publish','closed','closed','','3-bhk-independent-house-near-sahastradhara-road','','','2026-09-30 07:13:32','2026-09-30 01:43:32','',0,'http://localhost/realestate/property/3-bhk-independent-house-near-sahastradhara-road/',0,'property','',0),(13,0,'2026-09-27 07:13:33','2026-09-27 01:43:33','A stone-and-timber villa set on a hillside with uninterrupted views of the Doon valley and the lights of Dehradun at night.\n\nLarge picture windows, a fireplace lounge, a terrace deck and a landscaped garden make it ideal as a holiday home or boutique homestay.','Luxury 4 BHK Villa with Doon Valley View','A stone-and-timber villa set on a hillside with uninterrupted views of the Doon valley and the lights of Dehradun at night.','publish','closed','closed','','luxury-4-bhk-villa-with-doon-valley-view','','','2026-09-27 07:13:33','2026-09-27 01:43:33','',0,'http://localhost/realestate/property/luxury-4-bhk-villa-with-doon-valley-view/',0,'property','',0),(17,0,'2026-09-24 07:13:33','2026-09-24 01:43:33','A ready-to-move 2 BHK on the 4th floor of a well-maintained gated society on Rajpur Road, close to schools, cafés and Pacific Mall.','2 BHK Apartment in Gated Society, Rajpur Road','A ready-to-move 2 BHK on the 4th floor of a well-maintained gated society on Rajpur Road, close to schools, cafés and Pacific Mall.','publish','closed','closed','','2-bhk-apartment-in-gated-society-rajpur-road','','','2026-09-24 07:13:33','2026-09-24 01:43:33','',0,'http://localhost/realestate/property/2-bhk-apartment-in-gated-society-rajpur-road/',0,'property','',0),(21,0,'2026-09-21 07:13:34','2026-09-21 01:43:34','A fully furnished cottage a short walk from the Ganga at Tapovan, suited to long stays, yoga retreats or remote work.','Riverside Cottage near Tapovan','A fully furnished cottage a short walk from the Ganga at Tapovan, suited to long stays, yoga retreats or remote work.','publish','closed','closed','','riverside-cottage-near-tapovan','','','2026-09-21 07:13:34','2026-09-21 01:43:34','',0,'http://localhost/realestate/property/riverside-cottage-near-tapovan/',0,'property','',0),(25,0,'2026-09-18 07:13:35','2026-09-18 01:43:35','An east-facing residential plot in a developing colony with approved layout, internal roads and electricity already in place.','Residential Plot on Haridwar Bypass','An east-facing residential plot in a developing colony with approved layout, internal roads and electricity already in place.','publish','closed','closed','','residential-plot-on-haridwar-bypass','','','2026-09-18 07:13:35','2026-09-18 01:43:35','',0,'http://localhost/realestate/property/residential-plot-on-haridwar-bypass/',0,'property','',0),(29,0,'2026-09-15 07:13:35','2026-09-15 01:43:35','Terraced land with an established fruit orchard and a small storage hut, 25 minutes from Nainital with year-round road access.','Agricultural Land with Orchard','Terraced land with an established fruit orchard and a sm